@Test
public void testWithCounters() throws Throwable {
    createTable("CREATE TABLE %s (a int PRIMARY KEY, b counter)");
    execute("UPDATE %s SET b = b + 1 WHERE a = 1");
    execute("UPDATE %s SET b = b + 1 WHERE a = 1");
    assertRows(execute("SELECT b FROM %s WHERE a = 1"), row(2L));
    assertRows(execute("SELECT b + (tinyint) 1," + " b + (smallint) 1," + " b + 1," + " b + (bigint) 1," + " b + (float) 1.5," + " b + 1.5," + " b + (varint) 1," + " b + (decimal) 1.5," + " b + b FROM %s WHERE a = 1"), row(3L, 3L, 3L, 3L, 3.5, 3.5, BigInteger.valueOf(3), new BigDecimal("3.5"), 4L));
    assertRows(execute("SELECT b - (tinyint) 1," + " b - (smallint) 1," + " b - 1," + " b - (bigint) 1," + " b - (float) 1.5," + " b - 1.5," + " b - (varint) 1," + " b - (decimal) 1.5," + " b - b FROM %s WHERE a = 1"), row(1L, 1L, 1L, 1L, 0.5, 0.5, BigInteger.valueOf(1), new BigDecimal("0.5"), 0L));
    assertRows(execute("SELECT b * (tinyint) 1," + " b * (smallint) 1," + " b * 1," + " b * (bigint) 1," + " b * (float) 1.5," + " b * 1.5," + " b * (varint) 1," + " b * (decimal) 1.5," + " b * b FROM %s WHERE a = 1"), row(2L, 2L, 2L, 2L, 3.0, 3.0, BigInteger.valueOf(2), new BigDecimal("3.00"), 4L));
    assertRows(execute("SELECT b / (tinyint) 1," + " b / (smallint) 1," + " b / 1," + " b / (bigint) 1," + " b / (float) 0.5," + " b / 0.5," + " b / (varint) 1," + " b / (decimal) 0.5," + " b / b FROM %s WHERE a = 1"), row(2L, 2L, 2L, 2L, 4.0, 4.0, BigInteger.valueOf(2), new BigDecimal("4"), 1L));
    assertRows(execute("SELECT b %% (tinyint) 1," + " b %% (smallint) 1," + " b %% 1," + " b %% (bigint) 1," + " b %% (float) 0.5," + " b %% 0.5," + " b %% (varint) 1," + " b %% (decimal) 0.5," + " b %% b FROM %s WHERE a = 1"), row(0L, 0L, 0L, 0L, 0.0, 0.0, BigInteger.valueOf(0), new BigDecimal("0.0"), 0L));
    assertRows(execute("SELECT -b FROM %s WHERE a = 1"), row(-2L));
}

@Test
public void testPrecedenceAndParentheses() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, PRIMARY KEY(a, b))");
    execute("INSERT INTO %S (a, b, c, d) VALUES (2, 5, 25, 4)");
    UntypedResultSet rs = execute("SELECT a - c / b + d FROM %s");
    assertColumnNames(rs, "a - c / b + d");
    assertRows(rs, row(1));
    rs = execute("SELECT (c - b) / a + d FROM %s");
    assertColumnNames(rs, "(c - b) / a + d");
    assertRows(rs, row(14));
    rs = execute("SELECT c / a / b FROM %s");
    assertColumnNames(rs, "c / a / b");
    assertRows(rs, row(2));
    rs = execute("SELECT c / b / d FROM %s");
    assertColumnNames(rs, "c / b / d");
    assertRows(rs, row(1));
    rs = execute("SELECT (c - a) %% d / a FROM %s");
    assertColumnNames(rs, "(c - a) % d / a");
    assertRows(rs, row(1));
    rs = execute("SELECT (c - a) %% d / a + d FROM %s");
    assertColumnNames(rs, "(c - a) % d / a + d");
    assertRows(rs, row(5));
    rs = execute("SELECT -(c - a) %% d / a + d FROM %s");
    assertColumnNames(rs, "-(c - a) % d / a + d");
    assertRows(rs, row(3));
    rs = execute("SELECT (-c - a) %% d / a + d FROM %s");
    assertColumnNames(rs, "(-c - a) % d / a + d");
    assertRows(rs, row(3));
    rs = execute("SELECT c - a %% d / a + d FROM %s");
    assertColumnNames(rs, "c - a % d / a + d");
    assertRows(rs, row(28));
    rs = execute("SELECT (int)((c - a) %% d / (a + d)) FROM %s");
    assertColumnNames(rs, "(int)((c - a) % d / (a + d))");
    assertRows(rs, row(0));
    // test with aliases
    rs = execute("SELECT (int)((c - a) %% d / (a + d)) as result FROM %s");
    assertColumnNames(rs, "result");
    assertRows(rs, row(0));
    rs = execute("SELECT c / a / b as divisions FROM %s");
    assertColumnNames(rs, "divisions");
    assertRows(rs, row(2));
    assertRows(execute("SELECT * FROM %s WHERE a = ? AND b = (int) ? / 2 - 5", 2, 20), row(2, 5, 25, 4));
    assertRows(execute("SELECT * FROM %s WHERE a = ? AND b = (int) ? / (2 + 2)", 2, 20), row(2, 5, 25, 4));
}

