@Test
public void testOperationsWithDuration() throws Throwable {
    // Test with timestamp type.
    createTable("CREATE TABLE %s (pk int, time timestamp, v int, primary key (pk, time))");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:10:00 UTC', 1)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:12:00 UTC', 2)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:14:00 UTC', 3)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:15:00 UTC', 4)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:21:00 UTC', 5)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:22:00 UTC', 6)");
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time > ? - 5m", toTimestamp("2016-09-27 16:20:00 UTC")), row(1, toTimestamp("2016-09-27 16:21:00 UTC"), 5), row(1, toTimestamp("2016-09-27 16:22:00 UTC"), 6));
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time >= ? - 10m", toTimestamp("2016-09-27 16:25:00 UTC")), row(1, toTimestamp("2016-09-27 16:15:00 UTC"), 4), row(1, toTimestamp("2016-09-27 16:21:00 UTC"), 5), row(1, toTimestamp("2016-09-27 16:22:00 UTC"), 6));
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time >= ? + 5m", toTimestamp("2016-09-27 16:15:00 UTC")), row(1, toTimestamp("2016-09-27 16:21:00 UTC"), 5), row(1, toTimestamp("2016-09-27 16:22:00 UTC"), 6));
    assertRows(execute("SELECT time - 10m FROM %s WHERE pk = 1"), row(toTimestamp("2016-09-27 16:00:00 UTC")), row(toTimestamp("2016-09-27 16:02:00 UTC")), row(toTimestamp("2016-09-27 16:04:00 UTC")), row(toTimestamp("2016-09-27 16:05:00 UTC")), row(toTimestamp("2016-09-27 16:11:00 UTC")), row(toTimestamp("2016-09-27 16:12:00 UTC")));
    assertInvalidMessage("the '%' operation is not supported between time and 10m", "SELECT time %% 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the '*' operation is not supported between time and 10m", "SELECT time * 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the '/' operation is not supported between time and 10m", "SELECT time / 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the operation 'timestamp - duration' failed: The duration must have a millisecond precision. Was: 10us", "SELECT * FROM %s WHERE pk = 1 AND time > ? - 10us", toTimestamp("2016-09-27 16:15:00 UTC"));
    // Test with date type.
    createTable("CREATE TABLE %s (pk int, time date, v int, primary key (pk, time))");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27', 1)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-28', 2)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-29', 3)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-30', 4)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-10-01', 5)");
    execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-10-04', 6)");
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time > ? - 5d", toDate("2016-10-04")), row(1, toDate("2016-09-30"), 4), row(1, toDate("2016-10-01"), 5), row(1, toDate("2016-10-04"), 6));
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time > ? - 6d", toDate("2016-10-04")), row(1, toDate("2016-09-29"), 3), row(1, toDate("2016-09-30"), 4), row(1, toDate("2016-10-01"), 5), row(1, toDate("2016-10-04"), 6));
    assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND time >= ? + 1d", toDate("2016-10-01")), row(1, toDate("2016-10-04"), 6));
    assertRows(execute("SELECT time - 2d FROM %s WHERE pk = 1"), row(toDate("2016-09-25")), row(toDate("2016-09-26")), row(toDate("2016-09-27")), row(toDate("2016-09-28")), row(toDate("2016-09-29")), row(toDate("2016-10-02")));
    assertInvalidMessage("the '%' operation is not supported between time and 10m", "SELECT time %% 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the '*' operation is not supported between time and 10m", "SELECT time * 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the '/' operation is not supported between time and 10m", "SELECT time / 10m FROM %s WHERE pk = 1");
    assertInvalidMessage("the operation 'date - duration' failed: The duration must have a day precision. Was: 10m", "SELECT * FROM %s WHERE pk = 1 AND time > ? - 10m", toDate("2016-10-04"));
}

