    assertRows(execute("SELECT (" + containerType + "){m : {'pk' : pk, 'ck' : ck}} FROM %s"), row(userType("m", map("pk", 1, "ck", 1))), row(userType("m", map("pk", 1, "ck", 2))), row(userType("m", map("pk", 1, "ck", 3))));
    // Test Tuples nested within UDTs
    containerType = createType("CREATE TYPE %s(t tuple<int, int>, w tuple<bigint>)");
    assertRows(execute("SELECT (" + containerType + "){t : (pk, ck), w : (WRITETIME(t))} FROM %s"), row(userType("t", tuple(1, 1), "w", tuple(timestampInMicros))), row(userType("t", tuple(1, 2), "w", tuple(timestampInMicros))), row(userType("t", tuple(1, 3), "w", tuple(timestampInMicros))));
    // Test UDTs nested within Maps
    containerType = createType("CREATE TYPE %s(t frozen<" + type + ">)");
    assertRows(execute("SELECT (" + containerType + "){t : {a : min(ck), b: max(ck)}} FROM %s"), row(userType("t", userType("a", 1, "b", 3, "c", null))));
    assertRows(execute("SELECT (" + containerType + "){t : {a : pk, b : ck, c : WRITETIME(t)}} FROM %s"), row(userType("t", userType("a", 1, "b", 1, "c", timestampInMicros))), row(userType("t", userType("a", 1, "b", 2, "c", timestampInMicros))), row(userType("t", userType("a", 1, "b", 3, "c", timestampInMicros))));
    assertRows(execute("SELECT (" + containerType + "){t : {a : pk, b : ck, c : WRITETIME(t)}} FROM %s WHERE pk = 1 ORDER BY ck DESC"), row(userType("t", userType("a", 1, "b", 3, "c", timestampInMicros))), row(userType("t", userType("a", 1, "b", 2, "c", timestampInMicros))), row(userType("t", userType("a", 1, "b", 1, "c", timestampInMicros))));
    // Test Litteral Set with Duration elements
    assertInvalidMessage("Durations are not allowed inside sets: set<duration>", "SELECT pk, ck, (set<duration>){2d, 1mo} FROM %s");
    assertInvalidMessage("Invalid field selection: system.min(ck) of type int is not a user type", "SELECT min(ck).min FROM %s");
    assertInvalidMessage("Invalid field selection: (map<text, int>){'min': system.min(ck), 'max': system.max(ck)} of type frozen<map<text, int>> is not a user type", "SELECT (map<text, int>) {'min' : min(ck), 'max' : max(ck)}.min FROM %s");
}

@Test
public void testCollectionLiteralsWithDurations() throws Throwable {
    createTable("CREATE TABLE %s (pk int, ck int, d1 duration, d2 duration, PRIMARY KEY (pk, ck) )");
    execute("INSERT INTO %s (pk, ck, d1, d2) VALUES (1, 1, 15h, 13h)");
    execute("INSERT INTO %s (pk, ck, d1, d2) VALUES (1, 2, 10h, 12h)");
    execute("INSERT INTO %s (pk, ck, d1, d2) VALUES (1, 3, 11h, 13h)");
    assertRows(execute("SELECT [d1, d2] FROM %s"), row(list(Duration.from("15h"), Duration.from("13h"))), row(list(Duration.from("10h"), Duration.from("12h"))), row(list(Duration.from("11h"), Duration.from("13h"))));
    assertInvalidMessage("Durations are not allowed inside sets: frozen<set<duration>>", "SELECT {d1, d2} FROM %s");
    assertRows(execute("SELECT (map<int, duration>){ck : d1} FROM %s"), row(map(1, Duration.from("15h"))), row(map(2, Duration.from("10h"))), row(map(3, Duration.from("11h"))));
    assertInvalidMessage("Durations are not allowed as map keys: map<duration, int>", "SELECT (map<duration, int>){d1 : ck, d2 :ck} FROM %s");
}

@Test
public void testSelectUDTLiteral() throws Throwable {
    String type = createType("CREATE TYPE %s(a int, b text)");
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v " + type + ")");
    execute("INSERT INTO %s(k, v) VALUES (?, ?)", 0, userType("a", 3, "b", "foo"));
    assertInvalidMessage("Cannot infer type for term", "SELECT { a: 4, b: 'bar'} FROM %s");
    assertRows(execute("SELECT k, v, (" + type + "){ a: 4, b: 'bar'} FROM %s"), row(0, userType("a", 3, "b", "foo"), userType("a", 4, "b", "bar")));
    assertRows(execute("SELECT k, v, (" + type + ")({ a: 4, b: 'bar'}) FROM %s"), row(0, userType("a", 3, "b", "foo"), userType("a", 4, "b", "bar")));
    assertRows(execute("SELECT k, v, ((" + type + "){ a: 4, b: 'bar'}).a FROM %s"), row(0, userType("a", 3, "b", "foo"), 4));
    assertRows(execute("SELECT k, v, (" + type + "){ a: 4, b: 'bar'}.a FROM %s"), row(0, userType("a", 3, "b", "foo"), 4));
    assertInvalidMessage("Cannot infer type for term", "SELECT { a: 4} FROM %s");
    assertRows(execute("SELECT k, v, (" + type + "){ a: 4} FROM %s"), row(0, userType("a", 3, "b", "foo"), userType("a", 4, "b", null)));
    assertRows(execute("SELECT k, v, (" + type + "){ b: 'bar'} FROM %s"), row(0, userType("a", 3, "b", "foo"), userType("a", null, "b", "bar")));
    execute("INSERT INTO %s(k, v) VALUES (?, ?)", 1, userType("a", 5, "b", "foo"));
    assertRows(execute("SELECT (" + type + "){ a: max(v.a) , b: 'max'} FROM %s"), row(userType("a", 5, "b", "max")));
    assertRows(execute("SELECT (" + type + "){ a: min(v.a) , b: 'min'} FROM %s"), row(userType("a", 3, "b", "min")));
}

