        // SELECT toJson(column)
        assertRowsNet(executeNetWithPaging("SELECT toJson(k1), toJson(c1), toJson(value) FROM %s", pageSize), row("[\"" + uuid + "\", 2]", "[\"" + uuid + "\", 1]", "1"), row("[\"" + uuid + "\", 2]", "[\"" + uuid + "\", 2]", "2"), row("[\"" + uuid + "\", 2]", "[\"" + uuid + "\", 3]", "3"), row("[\"" + uuid + "\", 2]", "[\"" + uuid + "\", 4]", "4"));
