    for (int i = 0; i < WARN_THRESHOLD + 1; i++) execute("INSERT INTO %s (a, b, c ) VALUES ('key', 'cc" + i + "',  null);");
    try {
        execute("SELECT * FROM %s WHERE a = 'key';");
        assertEquals(oldWarnings + 1, cfs.metric.tombstoneWarnings.getCount());
