    String fStateNonNull = createFunction(KEYSPACE, "int, int", "CREATE OR REPLACE FUNCTION %s(state int, val int) " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE java\n" + "AS 'return Integer.valueOf(state + val);';");
