@Test
public void testInMarkerWithUDTs() throws Throwable {
    String typename = createType("CREATE TYPE %s (a int, b text)");
    String myType = KEYSPACE + '.' + typename;
    for (boolean frozen : new boolean[] { false, true }) {
        createTable(String.format("CREATE TABLE %%s (k int PRIMARY KEY, v %s)", frozen ? "frozen<" + myType + ">" : myType));
        Object v = userType("a", 0, "b", "abc");
        execute("INSERT INTO %s (k, v) VALUES (0, ?)", v);
        // Does not apply
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", userType("a", 1, "b", "abc"), userType("a", 0, "b", "ac")), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", userType("a", 1, "b", "abc"), null), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", null, null), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", userType("a", 1, "b", "abc"), unset()), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", unset(), unset()), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN ?", list(userType("a", 1, "b", "abc"), userType("a", 0, "b", "ac"))), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN (?, ?)", 1, 2), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN (?, ?)", 1, null), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN ?", list(1, 2)), row(false, v));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN (?, ?)", 1, unset()), row(false, v));
        // Does apply
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", userType("a", 0, "b", "abc"), userType("a", 0, "b", "ac")), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 1, b: 'bc'} WHERE k = 0 IF v IN (?, ?)", userType("a", 0, "b", "bc"), null), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'abc'} WHERE k = 0 IF v IN ?", list(userType("a", 1, "b", "bc"), userType("a", 0, "b", "ac"))), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 1, b: 'bc'} WHERE k = 0 IF v IN (?, ?, ?)", userType("a", 1, "b", "bc"), unset(), userType("a", 0, "b", "abc")), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN (?, ?)", 1, 0), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'abc'} WHERE k = 0 IF v.a IN (?, ?)", 0, null), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN ?", list(0, 1)), row(true));
        assertRows(execute("UPDATE %s SET v = {a: 0, b: 'abc'} WHERE k = 0 IF v.a IN (?, ?, ?)", 1, unset(), 0), row(true));
        assertInvalidMessage("Invalid null list in IN condition", "UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN ?", (List<ByteBuffer>) null);
        assertInvalidMessage("Invalid 'unset' value in condition", "UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v IN ?", unset());
        assertInvalidMessage("Invalid 'unset' value in condition", "UPDATE %s SET v = {a: 0, b: 'bc'} WHERE k = 0 IF v.a IN ?", unset());
    }
}

@Test
public void testConditionalOnDurationColumns() throws Throwable {
    createTable(" CREATE TABLE %s (k int PRIMARY KEY, v int, d duration)");
    assertInvalidMessage("Slice conditions ( > ) are not supported on durations", "UPDATE %s SET v = 3 WHERE k = 0 IF d > 1s");
    assertInvalidMessage("Slice conditions ( >= ) are not supported on durations", "UPDATE %s SET v = 3 WHERE k = 0 IF d >= 1s");
    assertInvalidMessage("Slice conditions ( <= ) are not supported on durations", "UPDATE %s SET v = 3 WHERE k = 0 IF d <= 1s");
    assertInvalidMessage("Slice conditions ( < ) are not supported on durations", "UPDATE %s SET v = 3 WHERE k = 0 IF d < 1s");
    execute("INSERT INTO %s (k, v, d) VALUES (1, 1, 2s)");
    assertRows(execute("UPDATE %s SET v = 4 WHERE k = 1 IF d = 1s"), row(false, Duration.from("2s")));
    assertRows(execute("UPDATE %s SET v = 3 WHERE k = 1 IF d = 2s"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, Duration.from("2s"), 3));
    assertRows(execute("UPDATE %s SET d = 10s WHERE k = 1 IF d != 2s"), row(false, Duration.from("2s")));
    assertRows(execute("UPDATE %s SET v = 6 WHERE k = 1 IF d != 1s"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, Duration.from("2s"), 6));
    assertRows(execute("UPDATE %s SET v = 5 WHERE k = 1 IF d IN (1s, 5s)"), row(false, Duration.from("2s")));
    assertRows(execute("UPDATE %s SET d = 10s WHERE k = 1 IF d IN (1s, 2s)"), row(true));
    assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, Duration.from("10s"), 6));
}

@Test
public void testConditionalOnDurationWithinLists() throws Throwable {
    for (Boolean frozen : new Boolean[] { Boolean.FALSE, Boolean.TRUE }) {
        String listType = String.format(frozen ? "frozen<%s>" : "%s", "list<duration>");
        createTable("CREATE TABLE %s (k int PRIMARY KEY, v int, l " + listType + " )");
        assertInvalidMessage("Slice conditions are not supported on collections containing durations", "UPDATE %s SET v = 3 WHERE k = 0 IF l > [1s, 2s]");
        assertInvalidMessage("Slice conditions are not supported on collections containing durations", "UPDATE %s SET v = 3 WHERE k = 0 IF l >= [1s, 2s]");
        assertInvalidMessage("Slice conditions are not supported on collections containing durations", "UPDATE %s SET v = 3 WHERE k = 0 IF l <= [1s, 2s]");
        assertInvalidMessage("Slice conditions are not supported on collections containing durations", "UPDATE %s SET v = 3 WHERE k = 0 IF l < [1s, 2s]");
        execute("INSERT INTO %s (k, v, l) VALUES (1, 1, [1s, 2s])");
        assertRows(execute("UPDATE %s SET v = 4 WHERE k = 1 IF l = [2s]"), row(false, list(Duration.from("1000ms"), Duration.from("2s"))));
        assertRows(execute("UPDATE %s SET v = 3 WHERE k = 1 IF l = [1s, 2s]"), row(true));
        assertRows(execute("SELECT * FROM %s WHERE k = 1"), row(1, list(Duration.from("1000ms"), Duration.from("2s")), 3));
