    assertRows(execute("SELECT a, b, s, count(b), count(s) FROM %s GROUP BY a, b PER PARTITION LIMIT 1"), row(1, 2, 1, 2L, 2L), row(2, 2, 2, 1L, 1L), row(4, 8, null, 1L, 0L), row(3, null, 3, 0L, 1L));
