        assertRowsNet(executeNetWithPaging("SELECT a, b, s, count(b), count(s) FROM %s WHERE a IN (1, 2, 3, 4) GROUP BY a", pageSize), row(1, 2, 1, 4L, 4L), row(2, 2, 2, 2L, 2L), row(3, null, 3, 0L, 1L), row(4, 8, null, 1L, 0L));
