        // Multi-partitions queries without aggregates
        assertRowsNet(executeNetWithPaging("SELECT a, b, s FROM %s WHERE a IN (1, 2, 3, 4) GROUP BY a", pageSize), row(1, 2, 1), row(2, 2, 2), row(3, null, 3), row(4, 8, null));
