@Test
public void testFilteringWithoutIndices() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, s int static, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 2, 4, 8)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 3, 6, 12)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 4, 4, 8)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (2, 3, 7, 12)");
    execute("UPDATE %s SET s = 1 WHERE a = 1");
    execute("UPDATE %s SET s = 2 WHERE a = 2");
    execute("UPDATE %s SET s = 3 WHERE a = 3");
    // Adds tomstones
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 1, 4, 8)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (2, 2, 7, 12)");
    execute("DELETE FROM %s WHERE a = 1 AND b = 1");
    execute("DELETE FROM %s WHERE a = 2 AND b = 2");
    beforeAndAfterFlush(() -> {
        // Checks filtering
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c = 4 AND d = 8");
        assertRows(execute("SELECT * FROM %s WHERE c = 4 AND d = 8 ALLOW FILTERING"), row(1, 2, 1, 4, 8), row(1, 4, 1, 4, 8));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND b = 4 AND d = 8");
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND b = 4 AND d = 8 ALLOW FILTERING"), row(1, 4, 1, 4, 8));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE s = 1 AND d = 12");
        assertRows(execute("SELECT * FROM %s WHERE s = 1 AND d = 12 ALLOW FILTERING"), row(1, 3, 1, 6, 12));
        assertInvalidMessage("IN predicates on non-primary-key columns (c) is not yet supported", "SELECT * FROM %s WHERE a IN (1, 2) AND c IN (6, 7)");
        assertInvalidMessage("IN predicates on non-primary-key columns (c) is not yet supported", "SELECT * FROM %s WHERE a IN (1, 2) AND c IN (6, 7) ALLOW FILTERING");
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c > 4");
        assertRows(execute("SELECT * FROM %s WHERE c > 4 ALLOW FILTERING"), row(1, 3, 1, 6, 12), row(2, 3, 2, 7, 12));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE s > 1");
        assertRows(execute("SELECT * FROM %s WHERE s > 1 ALLOW FILTERING"), row(2, 3, 2, 7, 12), row(3, null, 3, null, null));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE b < 3 AND c <= 4");
        assertRows(execute("SELECT * FROM %s WHERE b < 3 AND c <= 4 ALLOW FILTERING"), row(1, 2, 1, 4, 8));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c >= 3 AND c <= 6");
        assertRows(execute("SELECT * FROM %s WHERE c >= 3 AND c <= 6 ALLOW FILTERING"), row(1, 2, 1, 4, 8), row(1, 3, 1, 6, 12), row(1, 4, 1, 4, 8));
        assertRows(execute("SELECT * FROM %s WHERE s >= 1 LIMIT 2 ALLOW FILTERING"), row(1, 2, 1, 4, 8), row(1, 3, 1, 6, 12));
    });
    // Checks filtering with null
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c = null");
    assertInvalidMessage("Unsupported null value for column c", "SELECT * FROM %s WHERE c = null ALLOW FILTERING");
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c > null");
    assertInvalidMessage("Unsupported null value for column c", "SELECT * FROM %s WHERE c > null ALLOW FILTERING");
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE s > null");
    assertInvalidMessage("Unsupported null value for column s", "SELECT * FROM %s WHERE s > null ALLOW FILTERING");
    // Checks filtering with unset
    assertInvalidMessage("Unsupported unset value for column c", "SELECT * FROM %s WHERE c = ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column s", "SELECT * FROM %s WHERE s = ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column c", "SELECT * FROM %s WHERE c > ? ALLOW FILTERING", unset());
}

@Test
public void testFilteringWithoutIndicesWithCollections() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c list<int>, d set<int>, e map<int, int>, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 2, [1, 6], {2, 12}, {1: 6})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 3, [3, 2], {6, 4}, {3: 2})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 4, [1, 2], {2, 4}, {1: 2})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (2, 3, [3, 6], {6, 12}, {3: 6})");
    beforeAndAfterFlush(() -> {
        // Checks filtering for lists
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE c CONTAINS 2 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE c CONTAINS 2 AND c CONTAINS 3 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        // Checks filtering for sets
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE d CONTAINS 4");
        assertRows(execute("SELECT * FROM %s WHERE d CONTAINS 4 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE d CONTAINS 4 AND d CONTAINS 6 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        // Checks filtering for maps
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE e CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE e CONTAINS 2 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE e CONTAINS KEY 1 ALLOW FILTERING"), row(1, 2, list(1, 6), set(2, 12), map(1, 6)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE e[1] = 6 ALLOW FILTERING"), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE e CONTAINS KEY 1 AND e CONTAINS 2 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE c CONTAINS 2 AND d CONTAINS 4 AND e CONTAINS KEY 3 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
    });
    // Checks filtering with null
    assertInvalidMessage("Unsupported null value for column c", "SELECT * FROM %s WHERE c CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Unsupported null value for column d", "SELECT * FROM %s WHERE d CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Unsupported null value for column e", "SELECT * FROM %s WHERE e CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Unsupported null value for column e", "SELECT * FROM %s WHERE e CONTAINS KEY null ALLOW FILTERING");
    assertInvalidMessage("Unsupported null map key for column e", "SELECT * FROM %s WHERE e[null] = 2 ALLOW FILTERING");
    assertInvalidMessage("Unsupported null map value for column e", "SELECT * FROM %s WHERE e[1] = null ALLOW FILTERING");
    // Checks filtering with unset
    assertInvalidMessage("Unsupported unset value for column c", "SELECT * FROM %s WHERE c CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column d", "SELECT * FROM %s WHERE d CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column e", "SELECT * FROM %s WHERE e CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column e", "SELECT * FROM %s WHERE e CONTAINS KEY ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset map key for column e", "SELECT * FROM %s WHERE e[?] = 2 ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset map value for column e", "SELECT * FROM %s WHERE e[1] = ? ALLOW FILTERING", unset());
}

