        assertRows(executeFilteringOnly("SELECT a, b, c, d, s FROM %s WHERE c > 10 and c < 27 AND s = 29"), row(21, 22, 23, 24, 29));
        assertRows(executeFilteringOnly("SELECT a, b, c, d, s FROM %s WHERE c > 10 and c < 43 AND s = 29"), row(21, 22, 23, 24, 29), row(21, 26, 27, 28, 29));
        assertRows(executeFilteringOnly("SELECT a, b, c, d, s FROM %s WHERE c > 10 AND s > 15 AND s < 45"), row(21, 22, 23, 24, 29), row(21, 26, 27, 28, 29), row(31, 32, 33, 34, 35));
