/**
 * Check select with ith different column order. See CASSANDRA-10988
 */
@Test
public void testClusteringOrderWithSlice() throws Throwable {
    // non-compound, ASC order
    createTable("CREATE TABLE %s (a text, b int, PRIMARY KEY (a, b)) WITH CLUSTERING ORDER BY (b ASC)");
    execute("INSERT INTO %s (a, b) VALUES ('a', 2)");
    execute("INSERT INTO %s (a, b) VALUES ('a', 3)");
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0"), row("a", 2), row("a", 3));
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0 ORDER BY b DESC"), row("a", 3), row("a", 2));
    // non-compound, DESC order
    createTable("CREATE TABLE %s (a text, b int, PRIMARY KEY (a, b)) WITH CLUSTERING ORDER BY (b DESC)");
    execute("INSERT INTO %s (a, b) VALUES ('a', 2)");
    execute("INSERT INTO %s (a, b) VALUES ('a', 3)");
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0"), row("a", 3), row("a", 2));
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0 ORDER BY b ASC"), row("a", 2), row("a", 3));
    // compound, first column DESC order
    createTable("CREATE TABLE %s (a text, b int, c int, PRIMARY KEY (a, b, c)) WITH CLUSTERING ORDER BY (b DESC)");
    execute("INSERT INTO %s (a, b, c) VALUES ('a', 2, 4)");
    execute("INSERT INTO %s (a, b, c) VALUES ('a', 3, 5)");
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0"), row("a", 3, 5), row("a", 2, 4));
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0 ORDER BY b ASC"), row("a", 2, 4), row("a", 3, 5));
    // compound, mixed order
    createTable("CREATE TABLE %s (a text, b int, c int, PRIMARY KEY (a, b, c)) WITH CLUSTERING ORDER BY (b ASC, c DESC)");
    execute("INSERT INTO %s (a, b, c) VALUES ('a', 2, 4)");
    execute("INSERT INTO %s (a, b, c) VALUES ('a', 3, 5)");
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0"), row("a", 2, 4), row("a", 3, 5));
    assertRows(execute("SELECT * FROM %s WHERE a = 'a' AND b > 0 ORDER BY b ASC"), row("a", 2, 4), row("a", 3, 5));
}

@Test
public void testFilteringWithSecondaryIndex() throws Throwable {
    createTable("CREATE TABLE %s (pk int, " + "c1 int, " + "c2 int, " + "c3 int, " + "v int, " + "PRIMARY KEY (pk, c1, c2, c3))");
    createIndex("CREATE INDEX v_idx_1 ON %s (v);");
    for (int i = 1; i <= 5; i++) {
        execute("INSERT INTO %s (pk, c1, c2, c3, v) VALUES (?, ?, ?, ?, ?)", 1, 1, 1, 1, i);
        execute("INSERT INTO %s (pk, c1, c2, c3, v) VALUES (?, ?, ?, ?, ?)", 1, 1, 1, i, i);
        execute("INSERT INTO %s (pk, c1, c2, c3, v) VALUES (?, ?, ?, ?, ?)", 1, 1, i, i, i);
        execute("INSERT INTO %s (pk, c1, c2, c3, v) VALUES (?, ?, ?, ?, ?)", 1, i, i, i, i);
    }
    beforeAndAfterFlush(() -> {
        assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 > 0 AND c1 < 5 AND c2 = 1 AND v = 3 ALLOW FILTERING;"), row(1, 1, 1, 3, 3));
        assertEmpty(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 > 1 AND c1 < 5 AND c2 = 1 AND v = 3 ALLOW FILTERING;"));
        assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 > 1 AND c2 > 2 AND c3 > 2 AND v = 3 ALLOW FILTERING;"), row(1, 3, 3, 3, 3));
        assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 > 1 AND c2 > 2 AND c3 = 3 AND v = 3 ALLOW FILTERING;"), row(1, 3, 3, 3, 3));
        assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 IN(0,1,2) AND c2 = 1 AND v = 3 ALLOW FILTERING;"), row(1, 1, 1, 3, 3));
        assertRows(execute("SELECT * FROM %s WHERE pk = 1 AND  c1 IN(0,1,2) AND c2 = 1 AND v = 3"), row(1, 1, 1, 3, 3));
    });
}

