    assertInvalidMessage("Slice restrictions are not supported on duration columns", "SELECT * FROM %s WHERE d <= 1s ALLOW FILTERING");
    assertInvalidMessage("Slice restrictions are not supported on duration columns", "SELECT * FROM %s WHERE d < 1s ALLOW FILTERING");
}

