@Test
public void testStrictLivenessTombstone() throws Throwable {
    createTable("create table %s (p int primary key, v1 int, v2 int)");
    execute("USE " + keyspace());
    executeNet(protocolVersion, "USE " + keyspace());
    Keyspace ks = Keyspace.open(keyspace());
    createView("mv", "create materialized view %s as select * from %%s where p is not null and v1 is not null primary key (v1, p)" + " with gc_grace_seconds=5;");
    ColumnFamilyStore cfs = ks.getColumnFamilyStore("mv");
    cfs.disableAutoCompaction();
    updateView("Insert into %s (p, v1, v2) values (1, 1, 1) ;");
    assertRowsIgnoringOrder(execute("SELECT p, v1, v2 from mv"), row(1, 1, 1));
    updateView("Update %s set v1 = null WHERE p = 1");
    FBUtilities.waitOnFutures(ks.flush());
    assertRowsIgnoringOrder(execute("SELECT p, v1, v2 from mv"));
    // before gc grace second, strict-liveness tombstoned dead row remains
    cfs.forceMajorCompaction();
    assertEquals(1, cfs.getLiveSSTables().size());
    Thread.sleep(6000);
    // no auto compaction.
    assertEquals(1, cfs.getLiveSSTables().size());
    // after gc grace second, no data left
    cfs.forceMajorCompaction();
    assertEquals(0, cfs.getLiveSSTables().size());
    updateView("Update %s using ttl 5 set v1 = 1 WHERE p = 1");
    FBUtilities.waitOnFutures(ks.flush());
    assertRowsIgnoringOrder(execute("SELECT p, v1, v2 from mv"), row(1, 1, 1));
    // before ttl+gc_grace_second, strict-liveness ttled dead row remains
    cfs.forceMajorCompaction();
    assertEquals(1, cfs.getLiveSSTables().size());
    assertRowsIgnoringOrder(execute("SELECT p, v1, v2 from mv"), row(1, 1, 1));
    // after expired, before gc_grace_second
    Thread.sleep(5500);
    // before ttl+gc_grace_second, strict-liveness ttled dead row remains
    cfs.forceMajorCompaction();
    assertEquals(1, cfs.getLiveSSTables().size());
    assertRowsIgnoringOrder(execute("SELECT p, v1, v2 from mv"));
    // after expired + gc_grace_second
    Thread.sleep(5500);
    // no auto compaction.
    assertEquals(1, cfs.getLiveSSTables().size());
    // after gc grace second, no data left
    cfs.forceMajorCompaction();
    assertEquals(0, cfs.getLiveSSTables().size());
}

