@Test
public void testNeedsCleanup() throws Exception {
    // setup
    StorageService.instance.getTokenMetadata().clearUnsafe();
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore cfs = keyspace.getColumnFamilyStore(CF_STANDARD1);
    fillCF(cfs, "val", LOOPS);
    // prepare SSTable and some useful tokens
    SSTableReader ssTable = cfs.getLiveSSTables().iterator().next();
    final Token ssTableMin = ssTable.first.getToken();
    final Token ssTableMax = ssTable.last.getToken();
    final Token min = token((byte) 0);
    final Token before1 = token((byte) 2);
    final Token before2 = token((byte) 5);
    final Token before3 = token((byte) 10);
    final Token before4 = token((byte) 47);
    final Token insideSsTable1 = token((byte) 50);
    final Token insideSsTable2 = token((byte) 55);
    final Token max = token((byte) 127, (byte) 127, (byte) 127, (byte) 127);
    // test sanity check
    assert (min.compareTo(ssTableMin) < 0);
    assert (before1.compareTo(ssTableMin) < 0);
    assert (before2.compareTo(ssTableMin) < 0);
    assert (before3.compareTo(ssTableMin) < 0);
    assert (before4.compareTo(ssTableMin) < 0);
    assert (ssTableMin.compareTo(insideSsTable1) < 0);
    assert (insideSsTable1.compareTo(ssTableMax) < 0);
    assert (ssTableMin.compareTo(insideSsTable2) < 0);
    assert (insideSsTable2.compareTo(ssTableMax) < 0);
    assert (ssTableMax.compareTo(max) < 0);
    // test cases
    // key: needs cleanup?
    // value: owned ranges
    List<Map.Entry<Boolean, List<Range<Token>>>> testCases = new LinkedList<Map.Entry<Boolean, List<Range<Token>>>>() {

        {
            // SSTable owned as a whole
            add(entry(false, Arrays.asList(range(min, max))));
            // SSTable owned only partially
            add(entry(true, Arrays.asList(range(min, insideSsTable1))));
            // SSTable owned only partially
            add(entry(true, Arrays.asList(range(insideSsTable1, max))));
            // SSTable not owned at all
            add(entry(true, Arrays.asList(range(min, ssTableMin))));
            // only last token of SSTable is owned
            add(entry(true, Arrays.asList(range(ssTableMax, max))));
            // SSTable partially owned by two ranges
            add(entry(true, Arrays.asList(range(min, insideSsTable1), range(insideSsTable2, max))));
            // first token of SSTable is not owned
            add(entry(true, Arrays.asList(range(ssTableMin, ssTableMax))));
            // first token of SSTable is not owned
            add(entry(false, Arrays.asList(range(before4, max))));
            // SSTable owned by the last range
            add(entry(false, Arrays.asList(range(min, before1), range(before2, before3), range(before4, max))));
        }
    };
    // check all test cases
    for (Map.Entry<Boolean, List<Range<Token>>> testCase : testCases) {
        assertEquals(testCase.getKey(), CompactionManager.needsCleanup(ssTable, testCase.getValue()));
    }
}

@Test
public void testSizeMetric() {
    Keyspace keyspace = Keyspace.open("Keyspace1");
    ColumnFamilyStore cfs = keyspace.getColumnFamilyStore("Standard2");
    cfs.disableAutoCompaction();
    cfs.truncateBlocking();
    assertEquals(0, cfs.metric.liveDiskSpaceUsed.getCount());
    assertEquals(0, cfs.metric.totalDiskSpaceUsed.getCount());
    for (int j = 0; j < 10; j++) {
        new RowUpdateBuilder(cfs.metadata(), FBUtilities.timestampMicros(), String.valueOf(j)).clustering("0").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    }
    cfs.forceBlockingFlush();
    Collection<SSTableReader> sstables = cfs.getLiveSSTables();
    long size = 0;
    for (SSTableReader reader : sstables) {
        size += reader.bytesOnDisk();
    }
    // size metrics should show the sum of all SSTable sizes
    assertEquals(size, cfs.metric.liveDiskSpaceUsed.getCount());
    assertEquals(size, cfs.metric.totalDiskSpaceUsed.getCount());
    cfs.truncateBlocking();
    // after truncate, size metrics should be down to 0
    Util.spinAssertEquals(0L, () -> cfs.metric.liveDiskSpaceUsed.getCount(), 30);
    Util.spinAssertEquals(0L, () -> cfs.metric.totalDiskSpaceUsed.getCount(), 30);
    cfs.enableAutoCompaction();
}

@Test
public void testColUpdateTimeDeltaFiltering() {
    Keyspace keyspace = Keyspace.open("Keyspace1");
    ColumnFamilyStore store = keyspace.getColumnFamilyStore("Standard2");
    // This confirms another test/set up did not overflow the histogram
    store.metric.colUpdateTimeDeltaHistogram.cf.getSnapshot().get999thPercentile();
    new RowUpdateBuilder(store.metadata(), 0, "4242").clustering("0").add("val", ByteBufferUtil.bytes("0")).build().applyUnsafe();
    // The histogram should not have overflowed on the first write
    store.metric.colUpdateTimeDeltaHistogram.cf.getSnapshot().get999thPercentile();
    // smallest time delta that would overflow the histogram if unfiltered
    new RowUpdateBuilder(store.metadata(), 18165375903307L, "4242").clustering("0").add("val", ByteBufferUtil.bytes("0")).build().applyUnsafe();
    // CASSANDRA-11117 - update with large timestamp delta should not overflow the histogram
    store.metric.colUpdateTimeDeltaHistogram.cf.getSnapshot().get999thPercentile();
}

