            assertTrue(schema.startsWith("CREATE TABLE IF NOT EXISTS " + keyspace() + "." + tableName + " (\n" + "\tpk1 varint,\n" + "\tck1 varint,\n" + "\treg2 varint,\n" + "\treg1 frozen<tuple<frozen<tuple<varint, varint, varint>>, frozen<tuple<varint, varint, varint>>, frozen<tuple<varint, varint, varint>>>>,\n" + "\tPRIMARY KEY (pk1, ck1))"));
            assertTrue(schema.contains("ALTER TABLE " + keyspace() + "." + tableName + " DROP reg1 USING TIMESTAMP 10000;"));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    };
    // Validate before and after the type drop
    validate.run();
    schemaChange("DROP TYPE " + keyspace() + "." + typeB);
    schemaChange("DROP TYPE " + keyspace() + "." + typeA);
    validate.run();
}

