@Test
public void replaySimple() throws IOException {
    int cellCount = 0;
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(STANDARD1);
    final Mutation rm1 = new RowUpdateBuilder(cfs.metadata(), 0, "k1").clustering("bytes").add("val", bytes("this is a string")).build();
    cellCount += 1;
    CommitLog.instance.add(rm1);
    final Mutation rm2 = new RowUpdateBuilder(cfs.metadata(), 0, "k2").clustering("bytes").add("val", bytes("this is a string")).build();
    cellCount += 1;
    CommitLog.instance.add(rm2);
    CommitLog.instance.sync();
    SimpleCountingReplayer replayer = new SimpleCountingReplayer(CommitLog.instance, CommitLogPosition.NONE, cfs.metadata());
    List<String> activeSegments = CommitLog.instance.getActiveSegmentNames();
