    for (int i = 900; i < 1000; ++i) for (int j = 0; j < 8; ++j) execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?) USING TIMESTAMP ?", i, j * 2, 0, (long) j * 2);
    validateTimeSort();
    cfs.forceBlockingFlush();
