@Test(expected = EOFException.class)
public void channelRead_Closed() throws EOFException {
    int size = 8;
    buf = channel.alloc().buffer(size);
    Assert.assertEquals(1, buf.refCnt());
    buf.writerIndex(size);
    handler.close();
