    updates = new RowUpdateBuilder(cfs.metadata(), FBUtilities.timestampMicros() + 1, key);
    updates.addRangeTombstone(5, 7).build().apply();
    cfs.forceBlockingFlush();
    SSTableReader sstable = cfs.getLiveSSTables().iterator().next();
